<script>
const $=id=>document.getElementById(id);
let start=0,running=false,lastCycle=-1,spoken=false,ctx,gain;
const use=(id,x,y,s=1)=>
 `<g transform="translate(${x} ${y}) scale(${s})">
 <use href="#${id}"/></g>`;

function sound(){
 if(ctx){ctx.resume();return}
 ctx=new (window.AudioContext||window.webkitAudioContext)();
 const buffer=ctx.createBuffer(1,ctx.sampleRate*4,ctx.sampleRate);
 const data=buffer.getChannelData(0);
 for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1);
 const noise=ctx.createBufferSource();
 noise.buffer=buffer;noise.loop=true;
 const filter=ctx.createBiquadFilter();
 filter.type="lowpass";filter.frequency.value=4300;
 gain=ctx.createGain();gain.gain.value=.075;
 noise.connect(filter).connect(gain).connect(ctx.destination);
 noise.start();
}
function line(){
 if(!("speechSynthesis" in window))return;
 const u=new SpeechSynthesisUtterance("You came back.");
 u.lang="en-GB";u.rate=.8;u.pitch=.7;u.volume=.95;
 const voices=speechSynthesis.getVoices();
 const v=voices.find(v=>/Daniel|George|David|James/i.test(v.name));
 if(v)u.voice=v;
 speechSynthesis.speak(u);
}
function draw(now){
 if(!running)return;
 const elapsed=(now-start)/1000;
 const cycle=Math.floor(elapsed/30),t=elapsed%30;
 if(cycle!==lastCycle){lastCycle=cycle;spoken=false}
 const title=t<2||t>=28;
 $("title").style.display=title?"grid":"none";
 $("subtitle").style.opacity=t>=16&&t<18.8?1:0;
 $("status").textContent=
 `${Math.floor(t).toString().padStart(2,"0")} / 30 · illustrated animatic · loops`;
 $("rainLayer").setAttribute("transform",
  `translate(${-((t*38)%72)} ${((t*290)%80)})`);
 $("screen").setAttribute("viewBox","0 0 960 540");
 let a="";
 if(t<8){
  a=use("woman",425,370);
 }else if(t<15){
  const p=Math.min(1,(t-8)/5);
  const x=850-345*p;
  const bob=p<1?Math.sin(t*9)*2:0;
  a=use("woman",425,370)+use("man",x,370+bob)+
    use("umbrella",x-25,370+bob);
 }else if(t<21){
  $("screen").setAttribute("viewBox","345 132 260 147");
  a=use("woman",425,370)+use("man",505,370)+
    use("umbrella",470,370);
  if(t>=16&&!spoken){spoken=true;line()}
 }else{
  const p=Math.min(1,(t-21)/7);
  const scale=1-p*.4;
  const y=370-p*43;
  const bob=Math.sin((t-21)*7)*1.8;
  a=use("womanBack",425+p*80,y+bob,scale)+
    use("manBack",505+p*48,y-bob,scale)+
    use("umbrella",470+p*60,y,scale);
 }
 $("actors").innerHTML=a;
 requestAnimationFrame(draw);
}
$("play").onclick=()=>{
 if(running){
  running=false;
  if(gain)gain.gain.value=0;
  if("speechSynthesis" in window)speechSynthesis.cancel();
  $("play").textContent="Replay";
  return;
 }
 sound();gain.gain.value=.075;
 start=performance.now();lastCycle=-1;spoken=false;running=true;
 $("play").textContent="Stop";
 requestAnimationFrame(draw);
};
